"""Execute final saved-artifact replay; preserve pilot/development cells verbatim."""
from pathlib import Path
import json
import os
import copy
import nbformat as n
from nbclient import NotebookClient

ROOT=Path(__file__).resolve().parents[1]
PATH=ROOT/'notebooks/06_efficientad.ipynb'
OUT=ROOT/'reports/efficientad'


def main():
    nb=n.read(PATH,4)
    assert not nb.metadata.get('efficientad_final_replay'),'Final history already published; do not overwrite it'
    summary=json.loads((OUT/'summary.json').read_text());assert summary['models']==45
    cells=[]
    def md(s):cells.append(n.v4.new_markdown_cell(s))
    def code(s,dataset=False):
        c=n.v4.new_code_cell(s)
        if dataset:c.metadata['contains_dataset_images']=True
        cells.append(c)
    md('### Frozen final benchmark — executed research continuation\n\nThe preceding pilot and bounded-development cells and outputs are preserved as historical evidence. This continuation documents 45 newly trained and evaluated category-seed models, after the reduced protocol was frozen. Every cell below is **saved-artifact replay**, not live training. The live command was project Python `scripts/run_efficientad_final.py --all`; recovery uses its manifest, epoch snapshots and verified completed artifacts. No official test outcome changed training, scoring or calibration.')
    code("from pathlib import Path\nimport json,sys\nimport pandas as pd\nimport numpy as np\nimport matplotlib.pyplot as plt\nROOT=Path.cwd() if (Path.cwd()/'reports').exists() else Path.cwd().parent\nassert Path(sys.executable).resolve()==ROOT/'.venv/Scripts/python.exe'\nR=ROOT/'reports/efficientad'\nsummary=json.loads((R/'summary.json').read_text())\nruns=pd.read_csv(R/'all_runs.csv',float_precision='round_trip')\nmanifest=json.loads((R/'final/benchmark_manifest.json').read_text())\nfrozen=json.loads((ROOT/'configs/efficientad_reduced_frozen.json').read_text())\nmetrics=['image_auroc','image_ap','pixel_auroc','pixel_ap','au_pro','recall','fpr','precision','f1']\nprint({'models':len(runs),'categories':runs.category.nunique(),'seeds':sorted(runs.seed.unique().tolist()),'frozen_configuration':frozen,'replay':True})")
    md('Coverage is 15 categories by seeds 2026/2027/2028. Each model was freshly initialized and trained for nine full epochs. Frozen-file fields saying zero final models/evaluator not executed are immutable pre-benchmark metadata; the benchmark manifest and result records give current completion. Teacher normalization uses all fitting normals; teacher identity is unchanged. Both student heads and AE objectives remain trained, while the selected image/pixel map is the normalized local teacher/student discrepancy. No external penalty, test-guided border cropping, score clipping, sigmoid, smoothing or threshold tuning was introduced.')
    md('### Readiness, durability and the exact executed procedure\n\nReadiness checked the exact project interpreter, CUDA/RTX 4060, 15 categories, source/teacher/partition/freeze hashes, free disk and competing processes. Per-epoch snapshots contain model, optimizer, NumPy and torch CPU/CUDA RNG state. A run becomes complete only after official evaluation, checkpoint replay, exact score serialization, metric reconciliation and artifact hashing. The following source is displayed for scientific inspection; importing it does not launch fitting.')
    code("import inspect\nfrom anomaly_detection import efficientad_final as final\nprint((ROOT/'docs/efficientad_final_protocol.md').read_text(encoding='utf-8'))\nprint(inspect.getsource(final.train))\nprint(inspect.getsource(final.evaluate))\nprint('Resource gate:',json.loads((R/'final/resource_gate.json').read_text()))")
    md('This makes the chronological scientific operations inspectable: fit teacher moments, train exact fixed epochs, scale maps on development normals, save/replay the checkpoint, fit reserved-normal thresholds, then open test images and masks. Completed attempts are immutable; valid results are checked before skipping. Manager resource decisions depend on measured cost and disk availability, not test quality. Previous milestones and the successful pilot/development runs were not rerun.')
    md('### All 45 histories and learning curves\n\nThe plotted points are the actual recorded epoch means. All three seeds are shown per category, including fluctuations. Low training losses do not establish anomaly sensitivity; test ranking and calibrated operating metrics are reported separately. The AE remains trained even though its map was rejected during development selection.')
    code("categories=frozen['categories']\nfig,axes=plt.subplots(3,5,figsize=(15,8))\nfor ax,category in zip(axes.ravel(),categories):\n    for row in runs[runs.category.eq(category)].itertuples():\n        h=pd.read_csv(R/f'final/runs/{row.experiment_id}-history.csv')\n        ax.plot(h.epoch,h.hard,label=str(row.seed))\n    ax.set_title(category);ax.set_xlabel('Epoch');ax.set_ylabel('Hard loss');ax.legend(fontsize=7)\nfig.tight_layout();plt.show()\nfig,axes=plt.subplots(3,5,figsize=(15,8))\nfor ax,category in zip(axes.ravel(),categories):\n    for row in runs[runs.category.eq(category)].itertuples():\n        h=pd.read_csv(R/f'final/runs/{row.experiment_id}-history.csv')\n        ax.plot(h.epoch,h.autoencoder,label=f'AE/{row.seed}')\n        ax.plot(h.epoch,h.student_autoencoder,linestyle='--',label=f'STAE/{row.seed}')\n    ax.set_title(category);ax.set_xlabel('Epoch');ax.set_ylabel('Loss')\nfig.tight_layout();plt.show()\nprint(runs[['category','seed','training_seconds','calibration_seconds','evaluation_seconds']].to_string(index=False))")
    md('The full CSV histories and epoch snapshots preserve every final fit. They cannot be treated as extra development trials or used to choose a different epoch. Category and seed differences in these curves describe the frozen policy. All numerical failures or interrupted attempts, if any, remain in the append-only registry rather than being removed from the record.')
    md('### Native-resolution evaluation and uncertainty\n\nImage AUROC/AP and operating metrics use the shared metric implementation. Pixel AUROC/AP and AU-PRO use the exact native-resolution signed-score sweep, 8-connected regions and FPR<=.30 integration. Native maps are bilinear with align_corners=False. No probability conversion is applied. Whole-image bootstrap uses the same 2,000 resamples as previous models; pixel intervals alone use 4,096 calibration-centered/scaled monotone arctangent bins. Primary pixel point estimates remain exact.')
    code("print(inspect.getsource(final.native_evaluation))\nmacro=pd.DataFrame(summary['macro']).T\nprint(macro.to_string())\nprint('Pixel bootstrap quantization bias:',summary['pixel_bootstrap_quantization_bias'])\nprint('Macro by seed:');print(pd.read_csv(R/'macro_by_seed.csv').to_string(index=False))")
    md('The reported bootstrap intervals condition on fitted models and thresholds and do not include all fitting/calibration uncertainty. Pixel histogram bias is disclosed separately from primary exact metrics. Averaging seed replicates does not make repeated evaluations of the same test images independent. The point estimates below are arithmetic category means, equally weighted across all 15 categories and three seeds.')
    md('### All-category metrics, confusion matrices and defect types\n\nAll 45 runs and all nine metrics are displayed, followed by category means and seed-evaluation confusion counts. Defect-type tables compare each real defect class with that category’s test normals using the same frozen threshold. No category is excluded because it performs poorly.')
    code("print(runs[['category','seed']+metrics].to_string(index=False))\ncategory=pd.read_csv(R/'all_category_means.csv').set_index('category')\nprint(category.to_string())\nprint('Confusion counts across three seed-evaluations:');print(runs.groupby('category')[['tn','fp','fn','tp']].sum().to_string())\ndefects=pd.read_csv(R/'per_defect_results.csv')\nprint(defects.groupby(['category','defect'])[['auroc','ap','recall','fpr','precision','f1']].mean().to_string())\nprint('Textures versus objects:');print(pd.read_csv(R/'texture_object.csv').to_string(index=False))")
    md('These confusion counts sum repeated seed evaluations of the same images; they are not three times as many independent test cases. Texture/object averages and the full defect-type table expose behavior hidden by the macro mean. Genuine category-specific failures and small-defect cases are analyzed below, while the configuration remains unchanged.')
    md('### Reserved-normal calibration and score floors\n\nEach fresh model fits its own higher 95th-percentile threshold on the existing clean calibration partition, with strict greater comparison. Exact float32 score values are promoted before CSV export and parsed with round-trip precision. Report ties, sample sizes, empirical normal FPR and threshold sensitivity without using test labels to alter calibration.')
    code("calibration=pd.read_csv(R/'calibration_summary.csv',float_precision='round_trip')\nprint(calibration.to_string(index=False))\nprint({'normal_calibration_mean_fpr':summary['calibration_fpr_mean'],'test_macro_fpr':summary['test_fpr_macro'],'runs_with_ties':summary['calibration_runs_with_ties']})\nfig,axes=plt.subplots(1,2,figsize=(12,3))\nfor seed,g in calibration.groupby('seed'):\n    axes[0].plot(g.category,g.calibration_fpr,marker='.',label=str(seed))\n    axes[1].plot(g.category,g.fpr,marker='.',label=str(seed))\nfor ax,title in zip(axes,['Reserved normal empirical FPR','Official-test normal FPR']):\n    ax.axhline(.05,color='gray',linestyle='--');ax.set_title(title);ax.tick_params(axis='x',rotation=90);ax.legend()\nfig.tight_layout();plt.show()\nfor item in manifest['models']:\n    r=json.loads((ROOT/item['result']).read_text())\n    if item['category'] in ('bottle','carpet','leather','toothbrush'):\n        c=r['calibration'];print(item['category'],item['seed'],{k:c[k] for k in ['threshold','calibration_distribution','unique_calibration_scores','largest_tie_count','observed_calibration_fpr','bootstrap_threshold_p025_p50_p975','leave_one_out_threshold_range','future_fpr_order_statistic_95']})")
    md('A nominal 5% calibration rule does not guarantee 5% future FPR. Small samples, score ties and distribution differences are visible in the per-run records. Continuous-score Beta intervals are marked inapplicable when ties occur. Bottle’s border-driven normal score floor is retained rather than removed after seeing test results; a zero-width bootstrap on tied scores does not establish certainty.')
    md('### Genuine failure analysis across all 15 categories\n\nThe tables identify actual false alarms, misses, tiny masks, and image misses with a local pixel alarm overlapping the defect. Pixel overlap alone is not a guarantee of good localization. Genuine panels show original images, teacher/student and student/AE discrepancy maps, the unselected combination, selected-map pixel alarms and ground truth. Dataset-derived images remain in ignored local artifacts, following the project publication policy.')
    code("print(pd.read_csv(R/'category_failure_summary.csv').to_string(index=False))\nprint(pd.read_csv(R/'small_defect_summary.csv').to_string(index=False))\nexamples=pd.read_csv(R/'failure_examples.csv',float_precision='round_trip')\nprint(examples.to_string(index=False))\nprint('Image FN evaluations with localized pixel overlap:',summary['fn_with_pixel_overlap'])")
    md('The example inventory covers every category and records source paths, seeds, outcomes, threshold values and mask areas. No nonexistent false positive/negative is fabricated. Examine carpet/leather normal alarms, screw image detection, scratches and small defect masks in the retained panels. Background pixel alarm area documents localization spread; receptive-field or padding explanations remain hypotheses unless directly supported. Original MVTec AD is not a comprehensive logical-anomaly benchmark.')
    md('### Local anomaly-map panels — real executed output retained locally\n\nThe following replay displays the already generated genuine panels for all categories; it performs no model forward or feature extraction. The full executed notebook with these licensed dataset-derived outputs is saved under outputs/efficientad/final/. The Git notebook preserves the executed code and inventory, with image outputs removed. All aggregate charts and numeric outputs remain committed.')
    code("from IPython.display import display,Image as DisplayImage\nfor row in examples.itertuples():\n    display(DisplayImage(filename=str(ROOT/row.panel)))\n    if isinstance(row.zoom_panel,str):\n        display(DisplayImage(filename=str(ROOT/row.zoom_panel)))",dataset=True)
    md('The local full notebook contains the actual panels. Committed output removal is a publication/data-license choice, not a claim that the visualization cell was skipped. Global and combined maps are shown only for failure analysis and never replace the selected local score in the benchmark.')
    md('### Exact six-model comparison and paired uncertainty\n\nCompare all nine metrics from the exact recorded Basic CNN, convolutional autoencoder, PatchCore variant, SuperSimpleNet Lite, PaDiM and EfficientAD reduced-budget results. Category/seed matched image-bootstrap differences use shared draws. Paired category-resampling intervals cover all nine primary metrics with seed means inside categories; this measures a different uncertainty target from fixed-category image resampling.')
    code("comparison=pd.read_csv(R/'model_macro_comparison.csv',index_col=0)\nprint(comparison.to_string())\nprint(pd.read_csv(R/'paired_image_difference_intervals.csv').to_string(index=False))\nprint(pd.read_csv(R/'paired_category_difference_intervals.csv').to_string(index=False))\nprint(pd.read_csv(R/'paired_prediction_disagreements.csv').groupby('comparison').sum(numeric_only=True).drop(columns='seed').to_string())\nfig,ax=plt.subplots(figsize=(12,4))\na=comparison.T[metrics]\nim=ax.imshow(a.to_numpy(),vmin=0,vmax=1,cmap='viridis')\nax.set_xticks(range(len(metrics)),metrics,rotation=45,ha='right');ax.set_yticks(range(len(a)),a.index)\nfor i in range(len(a)):\n    for j in range(len(metrics)):ax.text(j,i,f'{a.iloc[i,j]:.3f}',ha='center',va='center',fontsize=8,color='white')\nfig.colorbar(im,ax=ax);fig.tight_layout();plt.show()")
    md('Lower FPR is favorable while higher values are generally favorable for the other metrics, so a single color scale is descriptive rather than an overall ranking. Previous results are untouched. No small difference in macro means is declared statistically superior; intervals are conditional/exploratory and no multiple-comparison correction is applied. Pixel bootstrap approximation and different fitting/latency scopes limit comparisons further.')
    md('### Actual runtime, memory, storage and deployment costs\n\nMeasured per-run training, calibration, test inference, native metrics/bootstrap, latency sweeps and total pipeline times replace projections. Model p50/p95 values are averages of 45 per-run percentiles, not pooled latency quantiles. End-to-end includes decoded-image preprocessing, transfer, full two-map eager execution and CPU map postprocessing; separate decode-inclusive timing is retained.')
    code("print(pd.read_csv(R/'model_cost_comparison.csv').to_string(index=False))\nprint(json.dumps({k:v for k,v in summary.items() if k not in ('macro','pixel_bootstrap_quantization_bias')},indent=2))\nprint(runs[['category','seed','training_seconds','calibration_seconds','inference_seconds','native_metrics_bootstrap_seconds','latency_seconds','wall_seconds','model_p50_ms','model_p95_ms','end_to_end_p50_ms','end_to_end_p95_ms','cpu_peak_rss_gib','train_peak_vram_gib','checkpoint_bytes']].to_string(index=False))")
    md(f"Actual training totals {summary['total_training_seconds']/3600:.3f} hours and run pipelines {summary['total_run_pipeline_seconds']/3600:.3f} hours. The historical projections were 2.68 training hours and 10.16 conservative total hours. Peak sampled worker RSS is {summary['peak_evaluation_cpu_rss_gib']:.3f} GiB. GPU allocator peaks exclude driver/context memory; manager RSS is separate. Recorded fitting effort excludes upstream teacher/backbone pretraining, and older Basic CNN/AE evaluation RAM was not recorded. Full two-map timing is conservative for a future optimized local-only deployment; no optimization was silently adopted here.")
    md('### Conclusions and complete retained research record\n\nThe full measured findings, category failure evidence, paired comparisons and limitations follow. This reduced variant preserves PDN teacher identity, short-budget training, missing penalty, global-branch rejection and calibration issues. It does not reproduce the paper’s 70k-step/penalty-trained model. All source/partition/teacher/checkpoint/map/score identities and prior milestone preservation are validated separately before publication. Notebook 07 — Final Model Comparison remains unstarted.')
    code("print((ROOT/'docs/efficientad_final_results.md').read_text(encoding='utf-8'))")
    md('This is the final frozen evaluation story, with the initial pilot, selected and rejected development trials, all final results and failures retained. The separate final validation report records coverage, deep artifact checks, notebook integrity and test outcomes. Remaining scientific limitations are not erased by completing the engineering benchmark.')
    replay=n.v4.new_notebook(cells=cells,metadata=nb.metadata)
    os.environ['IPYTHONDIR']=str(ROOT/'.cache/ipython-efficientad')
    os.environ['JUPYTER_RUNTIME_DIR']=str(ROOT/'.cache/jupyter-efficientad')
    os.environ['MPLCONFIGDIR']=str(ROOT/'.cache/matplotlib-efficientad')
    NotebookClient(replay,timeout=300,kernel_name='mvtec-research',resources={'metadata':{'path':str(ROOT)}}).execute()
    full=copy.deepcopy(nb);full.cells.extend(replay.cells)
    full.metadata['efficientad_final_replay']=dict(models=45,freeze_sha256=summary['frozen_configuration_sha256'],scope='saved-artifact replay')
    local=ROOT/'outputs/efficientad/final/06_efficientad.full.executed.ipynb';n.write(full,local)
    nb.cells.extend(replay.cells)
    nb.metadata['efficientad_final_replay']=dict(models=45,freeze_sha256=summary['frozen_configuration_sha256'],scope='saved-artifact replay')
    for cell in nb.cells:
        if cell.cell_type=='code' and cell.metadata.get('contains_dataset_images'):cell.outputs=[]
    nb.cells.insert(1,n.v4.new_markdown_cell('**Completed final benchmark:** all 45 frozen evaluations follow the preserved pilot/development history below. Historical pending statements remain as chronology. Final numeric outputs and aggregate plots are replayed from verified artifacts; licensed image panels are retained in the local full executed notebook. Notebook 07 is not started.'))
    n.write(nb,PATH)
    print('Published final replay; full dataset-derived output notebook local:',local)


if __name__=='__main__':main()
